<script setup lang="ts">definePageMeta({layout:'admin'});const q=ref(''),category=ref('');const {data}=await useFetch('/api/admin/inventory/overview',{query:{q,category},transform:(r:any)=>r.data});const {data:cats}=await useFetch('/api/admin/categories',{transform:(r:any)=>r.data})</script><template><div class="admin-page"><AdminPageHeader title="Stok" description="Pantau jumlah dan status persediaan."><NuxtLink class="btn btn-primary" to="/admin/stok/masuk">Barang Masuk</NuxtLink> <NuxtLink class="btn btn-outline" to="/admin/stok/keluar">Barang Keluar</NuxtLink></AdminPageHeader><div class="filters"><input v-model="q" class="field" placeholder="Cari produk atau SKU"><select v-model="category" class="field"><option value="">Semua kategori</option><option v-for="c in cats" :key="c.id" :value="c.slug">{{c.name}}</option></select></div><div class="table-wrap"><table class="data-table"><thead><tr><th>SKU</th><th>Produk</th><th>Kategori</th><th>Stok</th><th>Batas minimum</th><th>Status</th></tr></thead><tbody><tr v-for="x in data" :key="x.id"><td>{{x.sku}}</td><td><b>{{x.name}}</b></td><td>{{x.categoryName}}</td><td>{{x.stock}}</td><td>{{x.lowStockThreshold}}</td><td><ProductStockBadge :stock="x.stock" :threshold="x.lowStockThreshold"/></td></tr></tbody></table></div></div></template><style scoped>.filters{display:grid;grid-template-columns:1fr 220px;gap:.7rem}@media(max-width:600px){.filters{grid-template-columns:1fr}}</style>
